   function package_version return varchar2;

   /**
    * Nomor dokumen berikutnya: PREFIX-YYYY-NNNN (prefix dari apx_mbms_doc_types).
    * @param p_doc_type  jenis dokumen
    * @param p_date      tanggal dokumen (menentukan periode)
    * @return nomor dokumen
    */
   function next_no (
      p_doc_type in varchar2
     ,p_date     in date default sysdate
   ) return varchar2;
end apx_mbms_doc_pkg;
/

create or replace package body apx_mbms_doc_pkg as

   function package_version return varchar2
   is
   begin
      -- Version History:
      -- 01.00.00 2026-11-01 Tim PANDAWA  Generated by pandawa-apexlang
      return '01.00.00';
   end package_version;

   function next_no (
      p_doc_type in varchar2
     ,p_date     in date default sysdate
   ) return varchar2
   is
      l_prefix apx_mbms_doc_types.prefix%type;
      l_period apx_mbms_doc_seq.period%type := to_char(nvl(p_date, sysdate), 'YYYY');
      l_no     apx_mbms_doc_seq.last_no%type;
   begin
      select prefix
        into l_prefix
        from apx_mbms_doc_types
       where doc_type = p_doc_type;

      merge into apx_mbms_doc_seq s
      using (select p_doc_type doc_type
                   ,l_period   period
               from dual) n
         on (s.doc_type = n.doc_type and s.period = n.period)
       when not matched then
            insert (doc_type, period, last_no)
            values (n.doc_type, n.period, 0);

      update apx_mbms_doc_seq
         set last_no = last_no + 1
       where doc_type = p_doc_type
         and period   = l_period
      returning last_no into l_no;

      return l_prefix || '-' || l_period || '-' || lpad(l_no, 4, '0');
   end next_no;

end apx_mbms_doc_pkg;
/

create or replace package apx_mbms_approval_pkg as
   /**
    * Versi package (format XX.YY.ZZ).
    * @return versi
    */
   function package_version return varchar2;

   /**
    * TRUE saat perubahan status sedang dilakukan oleh package ini (dipakai trigger guard).
    * @return status bypass
