    * @param p_value  nilai bypass
    */
   procedure set_bypass (
      p_value in boolean
   );

   /**
    * Nilai dokumen untuk aturan approval (amount_expr di apx_mbms_doc_types).
    * @param p_doc_type  jenis dokumen
    * @param p_doc_id    id dokumen
    * @return nilai
    */
   function doc_amount (
      p_doc_type in varchar2
     ,p_doc_id   in number
   ) return number;

   /**
    * Ajukan dokumen DRAFT/REJECTED untuk approval.
    * @param p_doc_type  jenis dokumen
    * @param p_doc_id    id dokumen
    * @throws -20101..-20109  aturan approval dilanggar
    */
   procedure submit (
      p_doc_type in varchar2
     ,p_doc_id   in number
   );

   /**
    * Setujui satu langkah approval (maker-checker, cek role).
    * @param p_approval_id  id approval
    * @param p_note         catatan
    */
   procedure approve (
      p_approval_id in number
     ,p_note        in varchar2 default null
   );

   /**
    * Tolak satu langkah approval (catatan wajib).
    * @param p_approval_id  id approval
    * @param p_note         alasan penolakan
    */
   procedure reject (
      p_approval_id in number
     ,p_note        in varchar2
   );

   /**
    * Apakah user aktif boleh memproses approval ini.
    * @param p_approval_id  id approval
    * @return 'Y' atau 'N'
    */
   function can_act_yn (
      p_approval_id in number
   ) return varchar2;
end apx_mbms_approval_pkg;
