   if (updating or deleting) and not apx_mbms_approval_pkg.bypass then
      raise_application_error(-20120, 'Stock Transaction yang sudah tersimpan tidak dapat diubah atau dihapus. Buat transaksi koreksi.');
   end if;
   if deleting then
      return;
   end if;
   :new.txn_no := upper(:new.txn_no);
   if inserting then
      :new.created_by := apx_mbms_sec_pkg.app_user;
      :new.created_on := sysdate;
   end if;
   :new.updated_by := apx_mbms_sec_pkg.app_user;
   :new.updated_on := sysdate;
end;
/

