--------------------------------------------------------------------------------
-- Script : 01_inv_pkg.sql
-- Author : Tim PANDAWA
-- Date   : 2026-11-01
-- Purpose: Stock ledger helper (on hand, biaya rata-rata) - BR-04, BR-07
--------------------------------------------------------------------------------

create or replace package apx_mbms_inv_pkg as
   /**
    * Versi package (format XX.YY.ZZ).
    * @return versi
    */
   function package_version return varchar2;

   /**
    * Arah transaksi: +1 untuk RECEIPT/RETURN/ADJ_IN, -1 lainnya.
    * @param p_txn_type  tipe transaksi
    * @return 1 atau -1
    */
   function sign_of (
      p_txn_type in varchar2
   ) return number;

   /**
    * Stok on hand item di gudang/lokasi.
    * @param p_item_id       item
    * @param p_warehouse_id  gudang/lokasi
    * @return qty on hand
    */
   function on_hand (
      p_item_id      in number
     ,p_warehouse_id in number
   ) return number;

   /**
    * Biaya rata-rata (moving average dari transaksi masuk), fallback std cost.
    * @param p_item_id  item
    * @return biaya per unit
    */
   function avg_cost (
      p_item_id in number
   ) return number;
end apx_mbms_inv_pkg;
/

create or replace package body apx_mbms_inv_pkg as

   function package_version return varchar2
   is
   begin
      -- Version History:
      -- 01.00.00 2026-11-01 Tim PANDAWA  Port dari MBMS MVP (mnm-poc)
      return '01.00.00';
   end package_version;

   function sign_of (
      p_txn_type in varchar2
   ) return number
   is
   begin
      return case when p_txn_type in ('RECEIPT', 'RETURN', 'ADJ_IN') then 1 else -1 end;
   end sign_of;

   function on_hand (
      p_item_id      in number
     ,p_warehouse_id in number
   ) return number
   is
      l_qty number;
   begin
      select nvl(sum(qty_signed), 0)
        into l_qty
        from apx_mbms_stock_txns
       where item_id      = p_item_id
         and warehouse_id = p_warehouse_id;
      return l_qty;
   end on_hand;

   function avg_cost (
      p_item_id in number
   ) return number
   is
      l_cost number;
   begin
      select case when sum(qty) > 0 then round(sum(qty * nvl(unit_cost, 0)) / sum(qty), 2) end
        into l_cost
        from apx_mbms_stock_txns
       where item_id = p_item_id
         and txn_type in ('RECEIPT', 'ADJ_IN');
      if l_cost is null then
         select std_cost
           into l_cost
           from apx_mbms_items
          where item_id = p_item_id;
      end if;
      return l_cost;
   end avg_cost;

end apx_mbms_inv_pkg;
/

-- >>> database/custom/02_rules_pkg.sql
--------------------------------------------------------------------------------
-- Script : 02_rules_pkg.sql
-- Author : Tim PANDAWA
-- Date   : 2026-11-01
-- Purpose: Validate hook approval engine (BR-03 budget control, kelengkapan dokumen)
--------------------------------------------------------------------------------

create or replace package apx_mbms_rules_pkg as
   /**
    * Versi package (format XX.YY.ZZ).
    * @return versi
    */
   function package_version return varchar2;

   /**
    * Validasi submit budget proyek: wajib punya WBS.
    * @param p_doc_id  project_id
    * @throws -20204  proyek tanpa WBS
    */
   procedure check_project_submit (
      p_doc_id in number
   );

   /**
    * Validasi submit PR: wajib punya baris; PR proyek tidak boleh melebihi
    * sisa anggaran (budget - aktual - committed PR lain) - BR-03.
    * @param p_doc_id  pr_id
    * @throws -20203  PR tanpa baris
    * @throws -20201  anggaran tidak cukup
    */
   procedure check_pr_submit (
      p_doc_id in number
   );
end apx_mbms_rules_pkg;
/

create or replace package body apx_mbms_rules_pkg as

   function package_version return varchar2
   is
   begin
      -- Version History:
      -- 01.00.00 2026-11-01 Tim PANDAWA  Port dari MBMS MVP (mnm-poc)
      return '01.00.00';
   end package_version;

   procedure check_project_submit (
      p_doc_id in number
   )
   is
      l_count number;
   begin
      select count(*)
        into l_count
        from apx_mbms_wbs
       where project_id = p_doc_id;
      if l_count = 0 then
         raise_application_error(-20204, 'Proyek belum memiliki WBS/budget.');
      end if;
   end check_project_submit;

   procedure check_pr_submit (
      p_doc_id in number
   )
   is
      l_project_id apx_mbms_purchase_reqs.project_id%type;
      l_wbs_id     apx_mbms_purchase_reqs.wbs_id%type;
      l_lines      number;
      l_amount     number;
      l_budget     number;
      l_used       number;
      l_committed  number;
   begin
      select project_id
            ,wbs_id
        into l_project_id
            ,l_wbs_id
        from apx_mbms_purchase_reqs
       where pr_id = p_doc_id;

      select count(*)
            ,nvl(sum(line_amount), 0)
        into l_lines
            ,l_amount
        from apx_mbms_pr_lines
       where pr_id = p_doc_id;
      if l_lines = 0 then
         raise_application_error(-20203, 'PR belum memiliki baris item.');
      end if;

      if l_project_id is null then
         return;
      end if;

      select nvl(sum(budget_amount), 0)
        into l_budget
        from apx_mbms_wbs
       where project_id = l_project_id
         and (l_wbs_id is null or wbs_id = l_wbs_id);

      select nvl(-sum(qty_signed * nvl(unit_cost, 0)), 0)
        into l_used
        from apx_mbms_stock_txns
       where project_id = l_project_id
         and (l_wbs_id is null or wbs_id = l_wbs_id)
         and txn_type in ('ISSUE', 'RETURN');

      select nvl(sum(l.line_amount), 0)
        into l_committed
        from apx_mbms_purchase_reqs r
        join apx_mbms_pr_lines l on l.pr_id = r.pr_id
       where r.project_id = l_project_id
         and (l_wbs_id is null or r.wbs_id = l_wbs_id)
         and r.status in ('SUBMITTED', 'APPROVED')
         and r.pr_id <> p_doc_id;

      if l_amount > l_budget - l_used - l_committed then
         raise_application_error(-20201,
            'Anggaran tidak cukup. Sisa anggaran: ' || to_char(l_budget - l_used - l_committed, 'FM999G999G999G990')
            || ', nilai PR: ' || to_char(l_amount, 'FM999G999G999G990'));
      end if;
   end check_pr_submit;

end apx_mbms_rules_pkg;
/

-- >>> database/custom/03_stock_post_trg.sql
--------------------------------------------------------------------------------
-- Script : 03_stock_post_trg.sql
-- Author : Tim PANDAWA
-- Date   : 2026-11-01
-- Purpose: Posting stock ledger (BR-05, BR-07): BU dari gudang, arah qty, biaya
--          rata-rata, stok tidak boleh minus, issue hanya ke job/proyek approved,
--          nomor GR/MI/MR/ADJ. Berjalan setelah trigger generated (audit, immutable).
--------------------------------------------------------------------------------

create or replace trigger apx_mbms_stock_txns_post_trg
before insert on apx_mbms_stock_txns
for each row
follows apx_mbms_stock_txns_trg
declare
   l_on_hand number;
   l_status  varchar2(30);
begin
   select bu_id
     into :new.bu_id
     from apx_mbms_warehouses
    where warehouse_id = :new.warehouse_id;
   :new.qty_signed := :new.qty * apx_mbms_inv_pkg.sign_of(:new.txn_type);

   -- WBS harus milik proyek yang sama
   if :new.wbs_id is not null then
      select project_id
        into :new.project_id
        from apx_mbms_wbs
       where wbs_id = :new.wbs_id;
   end if;

   -- material hanya di-issue ke job/proyek yang sudah disetujui
   if :new.txn_type in ('ISSUE', 'RETURN') then
      if :new.job_id is null and :new.project_id is null then
         raise_application_error(-20250, 'Issue/return material wajib mereferensikan Job Order atau Proyek (BR-05).');
      elsif :new.job_id is not null then
         select status into l_status from apx_mbms_job_orders where job_id = :new.job_id;
      else
         select status into l_status from apx_mbms_projects where project_id = :new.project_id;
      end if;
      if l_status not in ('APPROVED', 'IN_PROGRESS', 'COMPLETED') then
         raise_application_error(-20251, 'Material hanya dapat di-issue ke job/proyek yang sudah disetujui (status: ' || l_status || ').');
      end if;
   end if;

   -- transaksi keluar: biaya rata-rata, stok tidak boleh minus
   if :new.qty_signed < 0 then
      if :new.unit_cost is null then
         :new.unit_cost := apx_mbms_inv_pkg.avg_cost(:new.item_id);
      end if;
      l_on_hand := apx_mbms_inv_pkg.on_hand(:new.item_id, :new.warehouse_id);
      if l_on_hand < :new.qty then
         raise_application_error(-20252, 'Stok tidak cukup. On hand: ' || l_on_hand || ', diminta: ' || :new.qty);
      end if;
   elsif :new.txn_type = 'RETURN' and :new.unit_cost is null then
      :new.unit_cost := apx_mbms_inv_pkg.avg_cost(:new.item_id);
   end if;

   if :new.txn_no is null then
      :new.txn_no := apx_mbms_doc_pkg.next_no(
                        case :new.txn_type
                           when 'RECEIPT' then 'GR'
                           when 'ISSUE'   then 'MI'
                           when 'RETURN'  then 'MR'
                           else 'ADJ'
                        end
                       ,:new.txn_date);
   end if;
end;
/

-- >>> database/custom/04_views.sql
--------------------------------------------------------------------------------
-- Script : 04_views.sql
-- Author : Tim PANDAWA
-- Date   : 2026-11-01
-- Purpose: View laporan & costing (dipakai halaman report dan dashboard)
--------------------------------------------------------------------------------

-- Posisi stok per item per gudang/lokasi
create or replace force view apx_mbms_stock_on_hand_v as
select w.warehouse_id
      ,w.wh_code
      ,w.wh_name
      ,i.item_id
      ,i.item_code
      ,i.item_name
      ,i.uom
      ,i.min_stock
      ,s.qty_on_hand
      ,apx_mbms_inv_pkg.avg_cost(i.item_id) avg_cost
      ,round(s.qty_on_hand * apx_mbms_inv_pkg.avg_cost(i.item_id), 2) stock_value
      ,case when s.qty_on_hand < i.min_stock then 'Y' else 'N' end below_min_yn
  from (select item_id
              ,warehouse_id
              ,sum(qty_signed) qty_on_hand
          from apx_mbms_stock_txns
         group by item_id, warehouse_id) s
  join apx_mbms_items i on i.item_id = s.item_id
  join apx_mbms_warehouses w on w.warehouse_id = s.warehouse_id;

-- Actual costing per job (D-07)
create or replace force view apx_mbms_job_cost_v as
select j.job_id
      ,j.job_no
      ,c.customer_name
      ,j.status
      ,j.qty_order
      ,j.qty_produced
      ,j.qty_reject
      ,j.insheet_pct
      ,case when j.qty_produced + j.qty_reject > 0
            then round(100 * j.qty_reject / (j.qty_produced + j.qty_reject), 2) end waste_pct
      ,j.selling_price
      ,j.est_hpp
      ,nvl(m.act_material, 0) act_material
      ,nvl(m.act_material, 0) + j.act_other_cost act_hpp
      ,j.est_hpp - (nvl(m.act_material, 0) + j.act_other_cost) hpp_variance
      ,case when j.selling_price > 0
            then round(100 * (j.selling_price - (nvl(m.act_material, 0) + j.act_other_cost)) / j.selling_price, 2) end act_margin_pct
  from apx_mbms_job_orders j
  left join apx_mbms_customers c on c.customer_id = j.customer_id
  left join (select job_id
                   ,-sum(qty_signed * nvl(unit_cost, 0)) act_material
               from apx_mbms_stock_txns
              where job_id is not null
                and txn_type in ('ISSUE', 'RETURN')
              group by job_id) m on m.job_id = j.job_id;

-- Budget vs actual per WBS
create or replace force view apx_mbms_wbs_budget_v as
select p.project_id
      ,p.project_no
      ,w.wbs_id
      ,w.wbs_code
      ,w.wbs_name
      ,w.budget_amount
      ,nvl(a.actual_amount, 0) actual_amount
      ,nvl(c.committed_amount, 0) committed_amount
      ,w.budget_amount - nvl(a.actual_amount, 0) - nvl(c.committed_amount, 0) remaining_amount
      ,case when w.budget_amount > 0
            then round(100 * (nvl(a.actual_amount, 0) + nvl(c.committed_amount, 0)) / w.budget_amount, 1) end used_pct
  from apx_mbms_wbs w
  join apx_mbms_projects p on p.project_id = w.project_id
  left join (select wbs_id
                   ,-sum(qty_signed * nvl(unit_cost, 0)) actual_amount
               from apx_mbms_stock_txns
              where wbs_id is not null
                and txn_type in ('ISSUE', 'RETURN')
              group by wbs_id) a on a.wbs_id = w.wbs_id
  left join (select r.wbs_id
                   ,sum(l.line_amount) committed_amount
               from apx_mbms_purchase_reqs r
               join apx_mbms_pr_lines l on l.pr_id = r.pr_id
              where r.wbs_id is not null
                and r.status in ('SUBMITTED', 'APPROVED')
              group by r.wbs_id) c on c.wbs_id = w.wbs_id;

-- Ringkasan proyek: kontrak, retensi, budget, aktual, peringatan
create or replace force view apx_mbms_project_summary_v as
select p.project_id
      ,p.project_no
      ,p.project_name
      ,c.customer_name
      ,p.status
      ,p.progress_pct
      ,p.contract_value
      ,round(p.contract_value * p.retention_pct / 100, 2) retention_amount
      ,nvl(b.budget_amount, 0) budget_amount
      ,nvl(a.actual_amount, 0) actual_amount
      ,nvl(b.budget_amount, 0) - nvl(a.actual_amount, 0) cost_variance
      ,case when nvl(b.budget_amount, 0) > p.contract_value then 'Y' else 'N' end loss_warning_yn
      ,case when p.end_date < trunc(sysdate) and p.status not in ('COMPLETED', 'CLOSED', 'CANCELLED') then 'Y' else 'N' end overdue_yn
  from apx_mbms_projects p
  join apx_mbms_customers c on c.customer_id = p.customer_id
  left join (select project_id, sum(budget_amount) budget_amount from apx_mbms_wbs group by project_id) b
         on b.project_id = p.project_id
  left join (select project_id
                   ,-sum(qty_signed * nvl(unit_cost, 0)) actual_amount
               from apx_mbms_stock_txns
              where project_id is not null
                and txn_type in ('ISSUE', 'RETURN')
              group by project_id) a on a.project_id = p.project_id;

